<script>
/* 2048 minimal implementation */
(function(){
  const size = 4;
  const boardEl = document.getElementById('board');
  const scoreEl = document.getElementById('score');
  const bestEl = document.getElementById('best');
  const bumpEl = document.getElementById('scoreBump');
  const newGameBtn = document.getElementById('newGame');
  const tabClassic = document.getElementById('tabClassic');
  const tabCupcakes = document.getElementById('tabCupcakes');

  let grid = [];
  let score = 0;
  let best = +localStorage.getItem('best-2048-replica') || 0;

  bestEl.textContent = best;

  // Layout helpers
  function px(n){ return n + 'px'; }
  function metrics(){
    const b = boardEl.getBoundingClientRect();
    const gap = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--gap')) || 16;
    const tile = (b.width - gap*5) / 4;
    return {gap, tile};
  }

  function positionFor(r,c){
    const {gap,tile} = metrics();
    const top = gap + r * (tile + gap);
    const left = gap + c * (tile + gap);
    return {top,left,size:tile};
  }

  // Build background cells once
  function buildBackground(){
    boardEl.innerHTML = '';
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        const cell = document.createElement('div');
        cell.className = 'cell';
        const {top,left} = positionFor(r,c);
        cell.style.top = px(top);
        cell.style.left = px(left);
        boardEl.appendChild(cell);
      }
    }
  }

  function randomEmptyCell(){
    const empties = [];
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        if(grid[r][c]===0) empties.push({r,c});
      }
    }
    if(!empties.length) return null;
    return empties[Math.floor(Math.random()*empties.length)];
  }

  function spawn(count=1){
    for(let i=0;i<count;i++){
      const spot = randomEmptyCell();
      if(!spot) return;
      grid[spot.r][spot.c] = Math.random()<0.9 ? 2 : 4;
    }
  }

  function setScore(s, bump=0){
    score = s;
    scoreEl.textContent = s;
    if(bump){
      bumpEl.textContent = '+'+bump;
      bumpEl.classList.add('show');
      setTimeout(()=>bumpEl.classList.remove('show'), 350);
    }
    if(score>best){
      best=score;
      bestEl.textContent = best;
      localStorage.setItem('best-2048-replica', best);
    }
  }

  function drawTiles(){
    // remove old tiles
    const olds = boardEl.querySelectorAll('.tile');
    olds.forEach(n=>n.remove());
    // draw new
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        const v = grid[r][c];
        if(!v) continue;
        const tile = document.createElement('div');
        tile.className = 'tile v'+v;
        const {top,left} = positionFor(r,c);
        tile.style.top = px(top);
        tile.style.left = px(left);
        tile.setAttribute('data-pos', r+'-'+c);
        tile.textContent = document.body.classList.contains('cupcakes') ? '🧁' : v;
        boardEl.appendChild(tile);
      }
    }
  }

  function init(){
    buildBackground();
    grid = Array.from({length:size}, ()=>Array(size).fill(0));
    setScore(0);
    spawn(2);
    drawTiles();
    boardEl.focus();
  }

  function canMove(){
    for(let r=0;r<size;r++){
      for(let c=0;c<size;c++){
        if(grid[r][c]===0) return true;
        if(c<size-1 && grid[r][c]===grid[r][c+1]) return true;
        if(r<size-1 && grid[r][c]===grid[r+1][c]) return true;
      }
    }
    return false;
  }

  function operate(line){
    // squeeze zeros
    const arr = line.filter(x=>x!==0);
    let scoreGain = 0;
    for(let i=0;i<arr.length-1;i++){
      if(arr[i]===arr[i+1]){
        arr[i]*=2;
        scoreGain += arr[i];
        arr.splice(i+1,1);
      }
    }
    while(arr.length<size) arr.push(0);
    return {arr, scoreGain};
  }

  function slideLeft(){
    let moved = false, gained = 0;
    for(let r=0;r<size;r++){
      const line = grid[r].slice();
      const {arr, scoreGain} = operate(line);
      if(arr.some((v, i) => v !== grid[r][i])) moved = true;
      grid[r] = arr;
      gained += scoreGain;
    }
    return {moved, gained};
  }

  function slideRight(){
    let moved=false, gained=0;
    for(let r=0;r<size;r++){
      const line = grid[r].slice().reverse();
      const {arr, scoreGain} = operate(line);
      const newLine = arr.reverse();
      if(newLine.some((v, i) => v !== grid[r][i])) moved = true;
      grid[r] = newLine;
      gained += scoreGain;
    }
    return {moved, gained};
  }

  function slideUp(){
    let moved=false, gained=0;
    for(let c=0;c<size;c++){
      const col = [];
      for(let r=0;r<size;r++) col.push(grid[r][c]);
      const {arr, scoreGain} = operate(col);
      for(let r=0;r<size;r++){
        if(grid[r][c]!==arr[r]) moved=true;
        grid[r][c]=arr[r];
      }
      gained += scoreGain;
    }
    return {moved, gained};
  }

  function slideDown(){
    let moved=false, gained=0;
    for(let c=0;c<size;c++){
      const col = [];
      for(let r=0;r<size;r++) col.push(grid[r][c]);
      const {arr, scoreGain} = operate(col.reverse());
      const out = arr.reverse();
      for(let r=0;r<size;r++){
        if(grid[r][c]!==out[r]) moved=true;
        grid[r][c]=out[r];
      }
      gained += scoreGain;
    }
    return {moved, gained};
  }

  function move(dir){
    let res;
    if(dir==='left') res = slideLeft();
    if(dir==='right') res = slideRight();
    if(dir==='up') res = slideUp();
    if(dir==='down') res = slideDown();
    if(!res) return;
    if(res.moved){
      spawn(1);
      setScore(score+res.gained, res.gained);
      drawTiles();
      if(!canMove()){
        setTimeout(()=>alert('Game over!'), 10);
      }
    }
  }

  // Keyboard
  document.addEventListener('keydown', (e)=>{
    const k = e.key;
    if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','a','A','d','D','w','W','s','S'].includes(k)){
      e.preventDefault();
      if(k==='ArrowLeft'||k==='a'||k==='A') move('left');
      if(k==='ArrowRight'||k==='d'||k==='D') move('right');
      if(k==='ArrowUp'||k==='w'||k==='W') move('up');
      if(k==='ArrowDown'||k==='s'||k==='S') move('down');
    }
  });

  // Swipe (pointer)
  let startX=0, startY=0, isPointer=false;
  boardEl.addEventListener('pointerdown', (e)=>{ isPointer=true; startX=e.clientX; startY=e.clientY; });
  boardEl.addEventListener('pointerup', (e)=>{
    if(!isPointer) return;
    isPointer=false;
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;
    const ax = Math.abs(dx), ay=Math.abs(dy);
    const thr = 24;
    if(Math.max(ax,ay)<thr) return;
    if(ax>ay) move(dx>0?'right':'left');
    else move(dy>0?'down':'up');
  });

  // New game
  newGameBtn.addEventListener('click', init);

  // Tabs
  tabClassic.addEventListener('click', ()=>{
    document.body.classList.remove('cupcakes');
    tabClassic.classList.add('active');
    tabCupcakes.classList.remove('active');
    tabClassic.setAttribute('aria-pressed', 'true');
    tabCupcakes.setAttribute('aria-pressed', 'false');
    drawTiles();
  });
  tabCupcakes.addEventListener('click', ()=>{
    document.body.classList.add('cupcakes');
    tabCupcakes.classList.add('active');
    tabClassic.classList.remove('active');
    tabClassic.setAttribute('aria-pressed', 'false');
    tabCupcakes.setAttribute('aria-pressed', 'true');
    drawTiles();
  });

  // Clickable game cards -> simple mock action
  document.querySelectorAll('.card.btn').forEach(card=>{
    card.addEventListener('click', ()=>{
      alert('This is a mock link for demo purposes.');
    });
  });

  // Initialize
  window.addEventListener('resize', ()=>{ buildBackground(); drawTiles(); });
  init();
})();
</script>
</body>
</html>
